export default function About() {
  return (
    <div className="about">
      <h2>About Us</h2>
      <p>
        Job Router is a simple React application designed to help users explore
        job-related pages in a clean and organized way. The app uses routing to
        move between sections like Home, About, Posts, and other pages without
        reloading the browser. It is built as a practice project to understand
        React components, navigation, and page structure while creating
        something useful for job searching and career planning.
      </p>
    </div>
  );
}
